-- Contract IDs are generated by the API: Contract_<the customer ID's digits>_<running number>, e.g.
-- Contract_001216_006. The running number counts contracts across all clients and comes from this
-- sequence, so no two contracts get the same one (a number is never reused, even after a delete).
-- It starts after the contracts already in the database.

CREATE SEQUENCE IF NOT EXISTS ctw_contract_seq;

SELECT setval('ctw_contract_seq', GREATEST(n, 1), n > 0) FROM (SELECT count(*) AS n FROM ctw_contract) c;

INSERT INTO ctw_migration (name) VALUES ('006_contract_id') ON CONFLICT DO NOTHING;
